import { readFileSync } from "node:fs"
import { expect, test, type Locator, type Page } from "@playwright/test"

// Generated by scripts/gen-e2e-inputs.ts; the spec must not import app code.
const {
  looks: LOOKS,
  clients: CLIENTS,
  componentPerGroup: GROUPS,
}: {
  looks: string[]
  clients: { id: string; homeLook: string }[]
  componentPerGroup: { group: string; name: string }[]
} = JSON.parse(readFileSync(new URL("./ids.json", import.meta.url), "utf8"))

test("the generated ids file lists looks, client pieces and groups", () => {
  expect(LOOKS.length).toBeGreaterThan(0)
  expect(CLIENTS.length).toBeGreaterThan(0)
  expect(GROUPS.length).toBeGreaterThan(0)
})

/** Collects console errors and uncaught page errors; nothing is filtered. */
function watchErrors(page: Page): string[] {
  const errors: string[] = []
  page.on("console", (m) => {
    if (m.type() === "error") errors.push(`console.error: ${m.text()}`)
  })
  page.on("pageerror", (e) => errors.push(`pageerror: ${e.message}`))
  return errors
}

const slug = (route: string) => route.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "") || "home"

async function expectNoSidewaysOverflow(page: Page, label: string) {
  const { scrollWidth, innerWidth } = await page.evaluate(() => ({
    scrollWidth: document.documentElement.scrollWidth,
    innerWidth: window.innerWidth,
  }))
  expect(scrollWidth, `${label}: scrollWidth ${scrollWidth} > innerWidth ${innerWidth}`).toBeLessThanOrEqual(innerWidth)
}

/** The piece's root, inside the preview frame, wears the look and has something visible inside it. */
async function expectPreviewRendered(page: Page, look: string) {
  const root = page.frameLocator("iframe").locator(".ds-root[data-theme]")
  await expect(root).toHaveAttribute("data-theme", look)
  await expect(root.locator("> *").first(), "preview root has visible content").toBeVisible()
}

/** Waits for the network to go quiet, for up to a few seconds. Chromium sometimes never reports "networkidle" for a
 *  page with a framed image although nothing is pending, so a miss is not a failure: the checks that follow wait for
 *  what they need themselves. */
async function settle(page: Page) {
  await page.waitForLoadState("networkidle", { timeout: 5000 }).catch(() => undefined)
}

/** Every image inside `scope` has loaded (a broken or still-pending image has no natural width). A lazy image
 *  below the fold does not load until it is near the screen, so each one is scrolled to first; the page is put
 *  back at the top afterwards. */
async function expectImagesLoaded(scope: Locator) {
  const images = scope.locator("img")
  for (let i = 0, n = await images.count(); i < n; i++) await images.nth(i).scrollIntoViewIfNeeded()
  await scope.page().evaluate(() => window.scrollTo(0, 0))
  await expect
    .poll(() => scope.evaluate((el) => Array.from(el.querySelectorAll("img")).every((img) => img.complete && img.naturalWidth > 0)))
    .toBe(true)
}

const p = (props: object) => Buffer.from(JSON.stringify(props)).toString("base64url")

const pages: { route: string; frameLook?: string; content?: string[] }[] = [
  // the existing site
  { route: "", content: ["h1"] },
  { route: "components", content: ["h1"] },
  ...GROUPS.map(({ name }) => ({ route: `components/${name}`, content: ["h1"] })),
  // Client work
  { route: "client", content: ["h1", "[data-card-view]"] },
  { route: "client/using", content: ["h1"] },
  { route: "client/styles/colour", content: ["h1"] },
  { route: "client/styles/type", content: ["h1"] },
  { route: "client/styles/motion", content: ["h1"] },
  ...CLIENTS.flatMap(({ id }) => LOOKS.map((look) => ({ route: `client/${id}?look=${look}`, frameLook: look, content: ["h1"] }))),
]

test.describe("site smoke", () => {
  for (const { route, frameLook, content } of pages) {
    test(`/${route}`, async ({ page }, info) => {
      const errors = watchErrors(page)
      await page.goto(route)
      await settle(page)

      for (const selector of content ?? []) await expect(page.locator(selector).first(), `${selector} visible`).toBeVisible()
      if (frameLook) {
        await expectPreviewRendered(page, frameLook)
        await expectImagesLoaded(page.frameLocator("iframe").locator("body"))
        const frameOverflow = await page
          .frameLocator("iframe")
          .locator("body")
          .evaluate(() => ({ s: document.documentElement.scrollWidth, w: window.innerWidth }))
        expect(frameOverflow.s, `iframe scrollWidth ${frameOverflow.s} > innerWidth ${frameOverflow.w}`).toBeLessThanOrEqual(frameOverflow.w)
      }
      await expectNoSidewaysOverflow(page, route || "home")

      await page.evaluate(() => document.fonts.ready)
      if (frameLook) await page.frameLocator("iframe").locator("body").evaluate(() => document.fonts.ready)
      await page.screenshot({ path: `e2e/shots/${info.project.name}/${slug(route)}.png`, fullPage: true })
      expect(errors).toEqual([])
    })
  }
})

const hoverStyle = (page: Page) =>
  page.locator(".ds-button").evaluate((el) => ({
    transitionDuration: getComputedStyle(el).transitionDuration,
    sheenAnimation: getComputedStyle(el, "::after").animationName,
    sheenTransition: getComputedStyle(el, "::after").transitionDuration,
  }))

async function hoverSheenButton(page: Page) {
  await page.goto(`client/preview/button?look=urlovematters&p=${p({ variant: "primary", hover: "sheen" })}`)
  const button = page.locator(".ds-button")
  await expect(button).toHaveClass(/ds-button--sheen/)
  await button.hover()
}

test("without reduced motion the button transitions (negative control)", async ({ page }) => {
  await page.emulateMedia({ reducedMotion: "no-preference" })
  await hoverSheenButton(page)
  const style = await hoverStyle(page)
  expect(style.transitionDuration).not.toBe("0s")
  expect(style.sheenTransition).not.toBe("0s")
})

test("reduced motion turns off transitions and sheen on hover", async ({ page }) => {
  await page.emulateMedia({ reducedMotion: "reduce" })
  await hoverSheenButton(page)
  const style = await hoverStyle(page)
  // The site's global reduced-motion rule (src/index.css) sets 0.01ms rather than 0s: effectively no animation.
  const seconds = (value: string) => value.split(",").map((part) => Number.parseFloat(part) * (part.trim().endsWith("ms") ? 0.001 : 1))
  for (const duration of [...seconds(style.transitionDuration), ...seconds(style.sheenTransition)]) expect(duration).toBeLessThan(0.001)
  expect(style.sheenAnimation).toBe("none")
})

test.describe("bad input does not crash", () => {
  test("/client/nope shows the not-found message", async ({ page }) => {
    const pageErrors: string[] = []
    page.on("pageerror", (e) => pageErrors.push(e.message))
    await page.goto("client/nope")
    await expect(page.getByRole("heading", { name: /nope/ })).toBeVisible()
    expect(pageErrors).toEqual([])
  })

  test("/client/button?look=bogus&p=%%% falls back to the Button page with a working preview", async ({ page }) => {
    const pageErrors: string[] = []
    page.on("pageerror", (e) => pageErrors.push(e.message))
    await page.goto("client/button?look=bogus&p=%%%")
    await expect(page.getByRole("heading", { level: 1, name: "Button" })).toBeVisible()
    await expectPreviewRendered(page, CLIENTS.find((c) => c.id === "button")!.homeLook)
    expect(pageErrors).toEqual([])
  })
})

test("the Photo preview loads its image", async ({ page }) => {
  await page.goto("client/preview/photo?look=wecuratelife")
  await expect(page.locator(".ds-photo img")).toHaveCount(1)
  await expectImagesLoaded(page.locator("body"))
})

test("the client index has no interactive element nested inside a link", async ({ page }) => {
  await page.goto("client")
  await expect(page.locator("[data-card-view]").first()).toBeVisible()
  expect(await page.locator("[data-card-view] .ds-root > *").count(), "cards with a live piece").toBeGreaterThanOrEqual(10)
  for (const card of await page.locator("[data-card-view] .ds-root").all()) await expect(card.locator("> *").first()).toBeVisible()
  await expect(page.locator("a a, a button, a input, a select, a textarea")).toHaveCount(0)
})

test("the site's Midnight theme does not leak into a piece: the preview wears its look's paper", async ({ page }) => {
  await page.goto("client/preview/button?look=wecuratelife")
  const read = async () => {
    await expect(page.locator(".ds-root")).toBeVisible()
    return page.evaluate(() => {
      const root = document.querySelector(".ds-root")!
      return {
        html: document.documentElement.dataset.theme ?? null,
        dark: document.documentElement.classList.contains("dark"),
        rootBackground: getComputedStyle(root).backgroundColor,
        paper: (() => {
          const probe = document.createElement("div")
          probe.style.backgroundColor = "var(--ds-color-paper)"
          root.append(probe)
          const colour = getComputedStyle(probe).backgroundColor
          probe.remove()
          return colour
        })(),
        bodyBackground: getComputedStyle(document.body).backgroundColor,
      }
    })
  }
  const light = await read()
  // Put the site on Midnight (`?theme=` is stored), so there is a dark theme to leak.
  await page.goto("client?theme=midnight")
  await expect(page.locator("html")).toHaveAttribute("data-theme", "midnight")
  await page.goto("client/preview/button?look=wecuratelife")
  const withMidnight = await read()
  // The preview route is outside the site's theme: nothing on <html>, and the paper is the look's own.
  expect(withMidnight.html).toBeNull()
  expect(withMidnight.dark).toBe(false)
  expect(withMidnight).toEqual(light)
  expect(withMidnight.rootBackground).toBe(withMidnight.paper)
  expect(withMidnight.rootBackground).not.toBe("rgba(0, 0, 0, 0)")
  expect(withMidnight.bodyBackground).toBe(withMidnight.rootBackground)
})

test("a nested look root overrides the outer look tokens", async ({ page }) => {
  await page.goto("client/styles/colour")
  // neutral has a 6px button radius and urlovematters has 0, so only a real override can read 0 inside.
  const radius = await page.evaluate(() => {
    document.body.insertAdjacentHTML(
      "beforeend",
      '<div class="ds-root" data-theme="neutral" id="out"><div class="ds-root" data-theme="urlovematters" id="in"></div></div>',
    )
    const read = (id: string) => getComputedStyle(document.getElementById(id)!).getPropertyValue("--ds-radius-button").trim()
    return { outer: read("out"), inner: read("in") }
  })
  expect(radius.outer).toBe("6px")
  expect(radius.inner).toBe("0")
})

test("the Modal opens in the preview, is named by its title, and Escape closes it and returns focus to the trigger", async ({ page }) => {
  await page.goto("client/preview/modal?look=urlovematters")
  const trigger = page.getByRole("button", { name: "Open dialog" })
  await expect(page.getByRole("dialog")).toHaveCount(0)
  await trigger.click()
  await expect(page.getByRole("dialog", { name: "A quiet moment" })).toBeVisible()
  await page.keyboard.press("Escape")
  await expect(page.getByRole("dialog")).toHaveCount(0)
  await expect(trigger).toBeFocused()
})
